24	
25	import type { StructuredLogMessage } from "openapi/requests/types.gen";
26	import AnsiRenderer from "src/components/AnsiRenderer";
27	import Time from "src/components/Time";
28	import { urlRegex } from "src/constants/urlRegex";
29	import { LogLevel, logLevelColorMapping } from "src/utils/logs";
30	
31	type Frame = {
32	  filename: string;
33	  lineno: number;
34	  name: string;
35	};
36	
37	type ErrorDetail = {
38	  exc_notes: Array<string>;
39	  exc_type: string;
40	  exc_value: string;
41	  frames: Array<Frame>;
42	  is_cause: boolean;
43	  syntax_error: string | null;
44	};
45	
46	type RenderStructuredLogProps = {
47	  index: number;
48	  logLevelFilters?: Array<string>;
49	  logLink: string;
50	  logMessage: string | StructuredLogMessage;
51	  renderingMode?: "jsx" | "text";
52	  showSource?: boolean;
53	  showTimestamp?: boolean;
54	  sourceFilters?: Array<string>;
55	  translate: TFunction;
56	};
57	
58	const addAnsiWithLinks = (line: string) => {
59	  const urlMatches = [...line.matchAll(urlRegex)];
60	
61	  if (!urlMatches.length) {
62	    return <AnsiRenderer linkify={false}>{line}</AnsiRenderer>;
63	  }
64	
65	  let currentIndex = 0;
66	  const elements: Array<React.ReactNode> = [];
67	
68	  urlMatches.forEach((match) => {
69	    const { index: startIndex } = match;
70	
71	    if (startIndex > currentIndex) {
72	      const textBeforeUrl = line.slice(currentIndex, startIndex);
73	
74	      elements.push(
75	        <AnsiRenderer key={`ansi-before-${textBeforeUrl}`} linkify={false}>
76	          {textBeforeUrl}
77	        </AnsiRenderer>,
78	      );
79	    }
80	
81	    elements.push(
82	      <Link
83	        color="fg.info"
84	        href={match[0]}
85	        key={`link-${match[0]}-${startIndex}`}
86	        rel="noopener noreferrer"
87	        target="_blank"
88	        textDecoration="underline"
89	      >
90	        {match[0]}
91	      </Link>,
92	    );
93	
94	    currentIndex = startIndex + match[0].length;
95	  });
96	
97	  if (currentIndex < line.length) {
98	    const textAfterUrl = line.slice(currentIndex);
99	
100	    elements.push(
101	      <AnsiRenderer key="ansi-after" linkify={false}>
102	        {textAfterUrl}
103	      </AnsiRenderer>,
104	    );
105	  }
106	
107	  return elements;
108	};
109	
110	const sourceFields = ["logger", "chan", "lineno", "filename", "loc"];
111	
112	const renderStructuredLogImpl = ({
113	  index,
114	  logLevelFilters,
115	  logLink,
116	  logMessage,
117	  renderingMode = "jsx",
118	  showSource = true,
119	  showTimestamp = true,
120	  sourceFilters,
121	  translate,
122	}: RenderStructuredLogProps): JSX.Element | string => {
123	  if (typeof logMessage === "string") {
124	    if (renderingMode === "text") {
125	      return logMessage;
126	    }
127	
128	    return (
129	      <chakra.span key={index} lineHeight={1.5}>
130	        {addAnsiWithLinks(logMessage)}
131	      </chakra.span>
132	    );
133	  }
134	
135	  const { event, level = undefined, timestamp, ...structured } = logMessage;
136	
137	  const elements = [];
138	
139	  if (
140	    logLevelFilters !== undefined &&
141	    Boolean(logLevelFilters.length) &&
142	    ((typeof level === "string" && !logLevelFilters.includes(level)) || !Boolean(level))
143	  ) {
144	    return "";
145	  }
146	
147	  if (
148	    sourceFilters !== undefined &&
149	    Boolean(sourceFilters.length) &&
150	    (("logger" in structured && !sourceFilters.includes(structured.logger as string)) ||
151	      !("logger" in structured))
152	  ) {
153	    return "";
154	  }
155	
156	  if (Boolean(timestamp) && showTimestamp) {
157	    if (renderingMode === "text") {
158	      elements.push(`[${timestamp}] `);
159	    } else {
160	      elements.push("[", <Time datetime={timestamp} key={0} />, "] ");
161	    }
162	  }
163	
164	  if (typeof level === "string") {
165	    const formattedLevel = level.toUpperCase();
166	
167	    if (renderingMode === "text") {
168	      elements.push(`${formattedLevel} - `);
169	    } else {
170	      elements.push(
171	        <Code
172	          colorPalette={level.toUpperCase() in LogLevel ? logLevelColorMapping[level as LogLevel] : undefined}
173	          key={1}
174	          lineHeight={1.5}
175	          minH={0}
176	          px={0}
177	        >
178	          {formattedLevel}
179	        </Code>,
180	        " - ",
181	      );
182	    }
183	  }
184	
185	  const { error_detail: errorDetail, ...reStructured } = structured;
186	  let details;
187	
188	  if (errorDetail !== undefined) {
189	    details = (errorDetail as Array<ErrorDetail>).map((error) => {
190	      const errorLines = error.frames.map((frame) => {
191	        if (renderingMode === "text") {
192	          return `    ${translate("components:logs.file")} ${frame.filename}, ${translate("components:logs.location", { line: frame.lineno, name: frame.name })}\n`;
193	        }
194	
195	        return (
196	          <chakra.p key={`frame-${frame.name}-${frame.filename}-${frame.lineno}`}>
197	            {translate("components:logs.file")}{" "}
198	            <chakra.span color="fg.info">{JSON.stringify(frame.filename)}</chakra.span>,{" "}
199	            {translate("components:logs.location", { line: frame.lineno, name: frame.name })}
200	          </chakra.p>
201	        );
202	      });
203	
204	      if (renderingMode === "text") {
205	        return `${error.exc_type}: ${error.exc_value}\n${(errorLines as Array<string>).join("")}`;
206	      }
207	
208	      return (
209	        <chakra.details key={error.exc_type} ms="20em" open={true}>
210	          <chakra.summary data-testid={`summary-${error.exc_type}`}>
211	            <chakra.span color="fg.info" cursor="pointer">
212	              {error.exc_type}: {error.exc_value}
213	            </chakra.span>
214	          </chakra.summary>
215	          {errorLines}
216	        </chakra.details>
217	      );
218	    });
219	  }
220	
221	  elements.push(
222	    renderingMode === "text" ? (
223	      event
224	    ) : (
225	      <chakra.span className="event" key={2} whiteSpace="pre-wrap">
226	        {addAnsiWithLinks(event)}
227	      </chakra.span>
228	    ),
229	  );
230	
231	  if (Object.hasOwn(reStructured, "filename") && Object.hasOwn(reStructured, "lineno")) {
232	    // eslint-disable-next-line @typescript-eslint/restrict-template-expressions
233	    reStructured.loc = `${reStructured.filename}:${reStructured.lineno}`;
234	    delete reStructured.filename;
235	    delete reStructured.lineno;
236	  }
237	
238	  for (const key in reStructured) {
239	    if (Object.hasOwn(reStructured, key)) {
240	      if (!showSource && sourceFields.includes(key)) {
241	        continue; // eslint-disable-line no-continue
242	      }
