19	import type { Virtualizer } from "@tanstack/react-virtual";
20	import type { TFunction } from "i18next";
21	
22	import type { TaskInstancesLogResponse } from "openapi/requests/types.gen";
23	import { renderStructuredLog } from "src/components/renderStructuredLog";
24	import { parseStreamingLogContent } from "src/utils/logs";
25	
26	type GetDownloadTextOptions = {
27	  fetchedData: TaskInstancesLogResponse | undefined;
28	  logLevelFilters: Array<string>;
29	  showSource: boolean;
30	  showTimestamp: boolean;
31	  sourceFilters: Array<string>;
32	  translate: TFunction;
33	};
34	
35	/**
36	 * Parse raw streaming log data into plain-text lines for log download.
37	 * Search matching now uses the searchableText array from useLogs instead,
38	 * which is derived from the rendered parsedLogs to stay aligned with log groups.
39	 */
40	export const getDownloadText = ({
41	  fetchedData,
42	  logLevelFilters,
43	  showSource,
44	  showTimestamp,
45	  sourceFilters,
46	  translate,
47	}: GetDownloadTextOptions): Array<string> => {
48	  const lines = parseStreamingLogContent(fetchedData);
49	
50	  return lines.map((line) =>
51	    renderStructuredLog({
52	      index: 0,
53	      logLevelFilters,
54	      logLink: "",
55	      logMessage: line,
56	      renderingMode: "text",
57	      showSource,
58	      showTimestamp,
59	      sourceFilters,
60	      translate,
61	    }),
62	  );
63	};
64	
65	export type HighlightOptions = {
66	  currentMatchLineIndex?: number;
67	  hash: string;
68	  index: number;
69	  searchMatchIndices?: Set<number>;
70	};
71	
72	/**
73	 * Returns the background color token for a virtualized log row.
74	 * Priority: current search match (yellow.emphasized) > URL hash line > transparent.
75	 * Non-current search matches use yellow.subtle for a softer highlight.
76	 */
77	export const getHighlightColor = ({
78	  currentMatchLineIndex,
79	  hash,
80	  index,
81	  searchMatchIndices,
82	}: HighlightOptions): string => {
83	  if (currentMatchLineIndex !== undefined && index === currentMatchLineIndex) {
84	    return "yellow.emphasized";
85	  }
86	  if (searchMatchIndices?.has(index)) {
87	    return "yellow.subtle";
88	  }
89	  if (Boolean(hash) && index === Number(hash) - 1) {
90	    return "brand.emphasized";
91	  }
92	
93	  return "transparent";
94	};
95	
96	/**
97	 * Wraps matching substrings in a log line with a highlight marker.
98	 * Returns an array of strings and { text, highlight } objects for rendering.
99	 */
100	export type HighlightSegment = { highlight: boolean; text: string };
101	
102	export const splitBySearchQuery = (text: string, query: string): Array<HighlightSegment> => {
103	  if (!query) {
104	    return [{ highlight: false, text }];
105	  }
106	
107	  const lowerText = text.toLowerCase();
108	  const lowerQuery = query.toLowerCase();
109	  const segments: Array<HighlightSegment> = [];
110	  let lastIndex = 0;
111	
112	  let matchIndex = lowerText.indexOf(lowerQuery, lastIndex);
113	
114	  while (matchIndex !== -1) {
115	    if (matchIndex > lastIndex) {
116	      segments.push({ highlight: false, text: text.slice(lastIndex, matchIndex) });
117	    }
118	    segments.push({ highlight: true, text: text.slice(matchIndex, matchIndex + query.length) });
119	    lastIndex = matchIndex + query.length;
120	    matchIndex = lowerText.indexOf(lowerQuery, lastIndex);
121	  }
122	
123	  if (lastIndex < text.length) {
124	    segments.push({ highlight: false, text: text.slice(lastIndex) });
125	  }
126	
127	  if (segments.length === 0) {
128	    return [{ highlight: false, text }];
129	  }
130	
131	  return segments;
132	};
133	
134	type VirtualizerInstance = Virtualizer<HTMLDivElement, Element>;
135	
136	type ScrollToTopOptions = {
137	  element: HTMLElement;
138	  virtualizer: VirtualizerInstance;
139	};
140	
141	type ScrollToBottomOptions = {
142	  element: HTMLElement;
143	  virtualizer: VirtualizerInstance;
144	};
145	
146	/**
147	 * Scroll to the top of the list
148	 */
149	export const scrollToTop = ({ element, virtualizer }: ScrollToTopOptions): void => {
150	  virtualizer.scrollToOffset(0);
151	  element.scrollTop = 0;
152	};
153	
154	/**
155	 * Scroll to the bottom of the list
156	 */
157	export const scrollToBottom = ({ element, virtualizer }: ScrollToBottomOptions): void => {
158	  const totalSize = virtualizer.getTotalSize();
159	  const clientHeight = element.clientHeight || 0;
160	  const offset = Math.max(0, totalSize - clientHeight);
161	
162	  virtualizer.scrollToOffset(offset);
163	  element.scrollTop = offset;
164	};
