import type { TFunction } from "i18next";
import { describe, expect, it } from "vitest";

import type { TaskInstancesLogResponse } from "openapi/requests/types.gen";
import { tiContextFields, renderTIContextPreamble } from "src/components/renderStructuredLog";

import { getDownloadText } from "./utils";

const translate = ((key: string) => key) as unknown as TFunction;

describe("tiContextFields", () => {
  it("is exactly 6 fields", () => {
    expect(tiContextFields).toHaveLength(6);
    expect(tiContextFields).toEqual(["ti_id", "dag_id", "task_id", "run_id", "try_number", "map_index"]);
  });
});

describe("renderTIContextPreamble text", () => {
  it("joins present fields with label", () => {
    const out = renderTIContextPreamble(
      { dag_id: "d", not_a_field: "x", run_id: "r", ti_id: "t" },
      "text",
      "Task Identity",
    );

    expect(out).toBe("Task Identity ti_id=t dag_id=d run_id=r");
  });

  it("no label", () => {
    expect(renderTIContextPreamble({ ti_id: "t" }, "text")).toBe("ti_id=t");
  });
});

describe("getDownloadText", () => {
  const fetchedData: TaskInstancesLogResponse = {
    content: [
      {
        event: "::group::Log message source details",
        sources: ["/x/attempt=1.log"],
        timestamp: null,
      },
      { event: "::endgroup::", timestamp: null },
      {
        dag_id: "log_grouping",
        event: "hello world",
        level: "info",
        map_index: -1,
        run_id: "manual__2025-02-18T12:19",
        task_id: "ti_context",
        ti_id: "01951900-16f6-7c1c-ae66-91bdfe9e0cfd",
        timestamp: "2025-09-11T17:44:52.597476Z",
        try_number: 1,
      },
    ],
    continuation_token: null,
  } as unknown as TaskInstancesLogResponse;

  it("inserts Task Identity preamble after first endgroup", () => {
    const lines = getDownloadText({
      fetchedData,
      logLevelFilters: [],
      showSource: false,
      showTimestamp: true,
      sourceFilters: [],
      translate,
    });

    const endIdx = lines.findIndex((l) => l.includes("::endgroup::"));
    const preamble = lines[endIdx + 1] ?? "";

    expect(preamble.startsWith("Task Identity ")).toBe(true);
    expect(preamble).toContain("ti_id=01951900-16f6-7c1c-ae66-91bdfe9e0cfd");

    const others = lines.filter((_l, i) => i !== endIdx + 1);

    others.forEach((l) => {
      expect(l).not.toContain("ti_id=");
      expect(l).not.toContain("dag_id=");
      expect(l).not.toContain("run_id=");
    });
    expect(lines.some((l) => l.includes("hello world"))).toBe(true);
  });

  it("no preamble when no TI fields", () => {
    const plain: TaskInstancesLogResponse = {
      content: [
        { event: "::group::Log message source details", sources: ["/x"], timestamp: null },
        { event: "::endgroup::", timestamp: null },
        { event: "hi", level: "info", timestamp: "2025-09-11T17:44:52.597476Z" },
      ],
      continuation_token: null,
    } as unknown as TaskInstancesLogResponse;

    const lines = getDownloadText({
      fetchedData: plain,
      logLevelFilters: [],
      showSource: false,
      showTimestamp: true,
      sourceFilters: [],
      translate,
    });

    expect(lines.some((l) => l.startsWith("Task Identity"))).toBe(false);
  });
});
