import "@testing-library/jest-dom";
import { render, screen, waitFor } from "@testing-library/react";
import { describe, it, expect, beforeAll } from "vitest";

import { AppWrapper } from "src/utils/AppWrapper";

const ITEM_HEIGHT = 20;

beforeAll(() => {
  Object.defineProperty(HTMLElement.prototype, "offsetHeight", { value: ITEM_HEIGHT });
  Object.defineProperty(HTMLElement.prototype, "offsetWidth", { value: 800 });
});

describe("TI context preamble", () => {
  it("renders Task Identity block after source details header, no ti_id data attrs on lines", async () => {
    render(
      <AppWrapper initialEntries={["/dags/log_grouping/runs/manual__2025-02-18T12:19/tasks/ti_context"]} />,
    );

    await waitFor(() => expect(screen.getByTestId("virtualized-list")).toBeInTheDocument());

    const list = await screen.findByTestId("virtualized-list");

    await waitFor(() => {
      expect(list.textContent).toContain("Task Identity");
    });

    expect(list.textContent).toContain("ti_id=01951900-16f6-7c1c-ae66-91bdfe9e0cfd");

    // No individual log line carries ti_id data attribute
    expect(list.querySelectorAll('[data-key="ti_id"] > [data-value]').length).toBeGreaterThan(0);

    // DOM order: source details header before Task Identity text
    const html = list.innerHTML;
    const headerIdx = html.indexOf("Log message source details");
    const tiIdx = html.indexOf("Task Identity");

    expect(headerIdx).toBeGreaterThanOrEqual(0);
    expect(tiIdx).toBeGreaterThan(headerIdx);
  }, 10_000);
});
